import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";
import { CjsSchema } from "@carbonenginejs/runtime/schema";
import { CjsBallparkController, CjsDestinyBall } from "@carbonenginejs/server/destiny";

// Numeric fixtures copied from CCP's Python tests, not generated by this port.
// Source: destiny/python/destiny/test/ballpark/evolve/test_{goto,follow,orbit,stop}.py
// See NOTICE for the donor's license.
const fixtures = JSON.parse(readFileSync(new URL("fixtures/carbon-trajectories.json", import.meta.url)));
const Mode = CjsDestinyBall.DSTBALLMODE;

// Source: destiny/python/destiny/test/helpers.py::create_space_ball
function spaceBall(park, id, x = 0, y = 0, z = 0)
{
    return park.AddBall(id, 13000000, 2, 10, true, false, true, false, false,
        x, y, z, 0, 0, 0, 0.9, 0.95);
}

function compareTrajectory(park, ball, expected, velocity = false)
{
    for (const [tick, point] of expected.entries())
    {
        park.Evolve();
        const actual = velocity ? [ball.vx, ball.vy, ball.vz] : [ball.x, ball.y, ball.z];
        for (let axis = 0; axis < 3; axis++)
        {
            assert.ok(Math.abs(actual[axis] - point[axis]) < 1e-10,
                `tick ${tick + 1}, axis ${axis}: ${actual[axis]} != ${point[axis]}`);
        }
    }
}

test("CCP GotoDirection trajectory", () =>
{
    const park = new CjsBallparkController();
    const ball = spaceBall(park, 1);
    park.GotoDirection(1, 10, 20, 30);
    compareTrajectory(park, ball, fixtures.test_goto_direction);
    assert.equal(park.currentTime, 10);
});

test("CCP GotoPoint trajectory including inertial overshoot", () =>
{
    const park = new CjsBallparkController();
    const ball = spaceBall(park, 1);
    park.GotoPoint(1, 10, 20, 30);
    compareTrajectory(park, ball, fixtures.test_goto_point);
});

test("CCP follow stationary target trajectory", () =>
{
    const park = new CjsBallparkController();
    const ball = spaceBall(park, 1);
    spaceBall(park, 2, 100, 200, 300);
    park.FollowBall(1, 2);
    compareTrajectory(park, ball, fixtures.test_follow_stopped_ball);
});

test("CCP follow moving target trajectory in either insertion order", () =>
{
    for (const reverse of [false, true])
    {
        const park = new CjsBallparkController();
        if (reverse) spaceBall(park, 2, 100);
        const ball = spaceBall(park, 1);
        if (!reverse) spaceBall(park, 2, 100);
        park.FollowBall(1, 2);
        park.GotoPoint(2, 0, 100, 200);
        compareTrajectory(park, ball, fixtures.test_follow_moving_ball);
    }
});

test("CCP legacy orbit trajectory and ID-dependent plane", () =>
{
    const park = new CjsBallparkController();
    spaceBall(park, 1);
    const ball = spaceBall(park, 2, 5);
    park.Orbit(2, 1, 1);
    compareTrajectory(park, ball, fixtures.test_orbit_ball);
});

test("CCP stopping velocities, including legacy vertical damping", () =>
{
    const park = new CjsBallparkController();
    const ball = spaceBall(park, 1);
    park.SetBallVelocity(1, 10, 20, 30);
    park.Stop(1);
    assert.equal(ball.vx, 10, "Stop changes mode rather than instantly zeroing velocity");
    compareTrajectory(park, ball, fixtures.test_stop_ball_in_goto_mode, true);
});

test("follow range is surface separation and handles coincident centers", () =>
{
    const park = new CjsBallparkController();
    const follower = spaceBall(park, 1, 100);
    const target = spaceBall(park, 2);
    park.SetBallRadius(2, 8);
    park.FollowBall(1, 2, 20);
    park.Evolve();
    assert.equal(follower.gotoX, 30);
    park.SetBallPosition(1, target.x, target.y, target.z);
    park.SetBallVelocity(1, 0, 0, 0);
    park.Evolve();
    assert.equal(follower.gotoX, target.x + 30);
    assert.ok(follower.vx > 0);
});

test("command transitions and removal detach all target links", () =>
{
    const park = new CjsBallparkController();
    const first = spaceBall(park, 1, 10);
    const second = spaceBall(park, 2, 20);
    const target = spaceBall(park, 3);
    park.FollowBall(1, 3, 10);
    park.Orbit(2, 3, 20);
    park.GotoPoint(1, 100, 0, 0);
    assert.equal(first.followId, 0);
    assert.deepEqual([...target._followers], [2]);
    park.FollowBall(1, 3, 10);
    park.RemoveBall(3);
    assert.equal(park.GetBall(3), null);
    assert.equal(target.isMoribund, true);
    for (const follower of [first, second])
    {
        assert.equal(follower.mode, Mode.DSTBALL_STOP);
        assert.equal(follower.followId, 0);
        assert.equal(follower._followPtr, null);
    }
    park.Evolve();
    park.ClearAll();
    assert.equal(park.GetBall(1), null);
    assert.equal(park.GetBall(2), null);
});

test("re-adding a target preserves handles and followers; re-adding a follower detaches it", () =>
{
    const park = new CjsBallparkController();
    const follower = spaceBall(park, 1);
    const target = spaceBall(park, 2, 100);
    park.FollowBall(1, 2, 10);
    assert.equal(spaceBall(park, 2, 200), target);
    assert.equal(follower._followPtr, target);
    park.Evolve();
    assert.equal(follower.gotoX, 186);
    assert.equal(spaceBall(park, 1), follower);
    assert.equal(follower.mode, Mode.DSTBALL_STOP);
    assert.equal(follower._followPtr, null);
    assert.equal(target._followers.size, 0);
});

test("invalid target commands preserve the existing order", () =>
{
    const park = new CjsBallparkController();
    const ball = spaceBall(park, 1);
    const target = spaceBall(park, 2);
    park.GotoPoint(1, 100, 20, 30);
    for (const command of ["FollowBall", "Orbit"])
    {
        park[command](1, 1, 10);
        park[command](1, 999, 10);
        park[command](1, 2, NaN);
        target.isCloaked = true;
        park[command](1, 2, 10);
        target.isCloaked = false;
        target.isMoribund = true;
        park[command](1, 2, 10);
        target.isMoribund = false;
    }
    park.GotoPoint(1, NaN, 0, 0);
    park.GotoDirection(1, Infinity, 0, 0);
    assert.equal(ball.mode, Mode.DSTBALL_GOTO);
    assert.deepEqual([ball.gotoX, ball.gotoY, ball.gotoZ], [100, 20, 30]);
    park.Stop(999);
    park.RemoveBall(999);
    assert.equal(park.GetBall(999), null);
});

test("throttle clamp and GotoPoint restart match native controls", () =>
{
    const park = new CjsBallparkController();
    const ball = spaceBall(park, 1);
    park.SetSpeedFraction(1, -1);
    assert.equal(ball.speedFraction, 0);
    park.GotoPoint(1, 100, 0, 0);
    assert.equal(ball.speedFraction, 1);
    park.SetSpeedFraction(1, 5);
    assert.equal(ball.speedFraction, 1);
    park.SetSpeedFraction(1, NaN);
    assert.equal(ball.speedFraction, 1);
    park.SetSpeedFraction(1, 0);
    park.Evolve();
    assert.equal(ball.x, 0);
});

test("static objects do not evolve; freezing a mobile object stops it", () =>
{
    const park = new CjsBallparkController();
    const ball = spaceBall(park, 1, 50);
    park.GotoPoint(1, 100, 0, 0);
    park.Evolve();
    park.SetBallFree(1, false);
    const x = ball.x;
    assert.equal(ball.vx, 0);
    assert.equal(ball.mode, Mode.DSTBALL_STOP);
    park.GotoPoint(1, 1000, 0, 0);
    park.Evolve();
    assert.equal(ball.x, x);
    park.SetBallFree(1, true);
    park.Evolve();
    assert.ok(ball.x > x);
});

test("mass and agility setters recompute drag; invalid values do not replace it", () =>
{
    const park = new CjsBallparkController();
    const ball = spaceBall(park, 1);
    park.SetBallMass(1, 2000000);
    park.SetBallAgility(1, 0.5);
    park.SetBallMass(1, 0);
    park.SetBallAgility(1, Infinity);
    park.SetBallVelocity(1, 10, 0, 0);
    park.Evolve();
    assert.ok(Math.abs(ball.vx - 10 * Math.exp(-1)) < 1e-12);
    park.SetMaxSpeed(1, 12.3);
    assert.equal(ball.maxVelocity, Math.fround(12.3));
});

test("unsupported mode and zero mobile mass fail before any tick mutation", () =>
{
    const park = new CjsBallparkController();
    const first = spaceBall(park, 1);
    const second = spaceBall(park, 2);
    park.GotoPoint(1, 100, 0, 0);
    second.mode = Mode.DSTBALL_WARP;
    assert.throws(() => park.Evolve(), /not implemented/);
    assert.equal(first.x, 0);
    assert.equal(park.currentTime, 0);
    park.Stop(2);
    second.mass = 0;
    assert.throws(() => park.Evolve(), /positive finite/);
    assert.equal(park.currentTime, 0);
    assert.throws(() => spaceBall(park, 2 ** 53), /safe integers/);
});

test("coincident zero-radius orbit stays finite (documented adaptation)", () =>
{
    const park = new CjsBallparkController();
    const ball = spaceBall(park, 1);
    spaceBall(park, 2);
    park.SetBallRadius(1, 0);
    park.SetBallRadius(2, 0);
    park.Orbit(1, 2, 0);
    for (let tick = 0; tick < 10; tick++) park.Evolve();
    assert.deepEqual([ball.x, ball.y, ball.z], [0, 0, 0]);
});

test("double-precision positions retain small movement at large coordinates", () =>
{
    const park = new CjsBallparkController();
    const ball = spaceBall(park, 1, 1e12);
    park.GotoPoint(1, 1e12 + 1000, 0, 0);
    park.Evolve();
    assert.ok(ball.x > 1e12 && ball.x < 1e12 + 1);
});

test("decorated classes register schema fields and honest donor identities", () =>
{
    new CjsDestinyBall();
    new CjsBallparkController();
    assert.ok(CjsSchema.getField(CjsDestinyBall, "mass"));
    assert.ok(CjsSchema.getField(CjsBallparkController, "time"));
    assert.equal(CjsSchema.getSchema(CjsDestinyBall).modelledOn, "Ball");
    assert.equal(CjsSchema.getSchema(CjsBallparkController).modelledOn, "Ballpark");
});
